// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Modified {
    uint256 public value;

    modifier positive(uint256 x) {
        require(x > 0);
        _;
        value += 1;
    }

    function set(uint256 newValue) public positive(newValue) {
        value = newValue;
    }
}
